  7: /// <summary>
  8: /// TEST-MCP-USECASE-020: Consumer contracts for causal PostgreSQL cancellation classification.
  9: /// </summary>
 10: public sealed class BugTriage139SixteenthPostgreSqlContractTests
 11: {
 12:     /// <summary>
 13:     /// A server statement timeout remains a provider failure even when the caller token is
 14:     /// concurrently cancelled.
 15:     /// </summary>
 16:     [Fact]
 17:     public async Task ProviderCancellation_ServerStatementTimeout_IsNotCallerCancellation()
 18:     {
 19:         using var caller = new CancellationTokenSource();
 20:         caller.Cancel();
 21:         var providerException = CreateQueryCancelled(
 22:             "canceling statement due to statement timeout");
 23: 
 24:         var observed = await Assert.ThrowsAsync<PostgresException>(
 25:                 () => InvokeProviderCancelableAsync(
 26:                     () => Task.FromException<int>(providerException),
 27:                     caller.Token))
 28:             .ConfigureAwait(true);
 29: 
 30:         Assert.Same(providerException, observed);
 31:     }
 32: 
 33:     /// <summary>
 34:     /// Administrative cancellation cannot be attributed to the caller merely because the caller
 35:     /// token is concurrently cancelled.
 36:     /// </summary>
 37:     [Fact]
 38:     public async Task ProviderCancellation_AdministrativeCancel_IsNotCallerCancellation()
 39:     {
 40:         using var caller = new CancellationTokenSource();
 41:         caller.Cancel();
 42:         var providerException = CreateQueryCancelled(
 43:             "canceling statement due to administrator command");
 44: 
 45:         var observed = await Assert.ThrowsAsync<PostgresException>(
 46:                 () => InvokeProviderCancelableAsync(
 47:                     () => Task.FromException<int>(providerException),
 48:                     caller.Token))
 49:             .ConfigureAwait(true);
 50: 
 51:         Assert.Same(providerException, observed);
 52:     }
 53: 
 54:     /// <summary>
 55:     /// An operation-cancel exception carrying the exact caller token remains caller cancellation.
 56:     /// </summary>
 57:     [Fact]
 58:     public async Task ProviderCancellation_ExactCallerToken_RemainsCancellation()
 59:     {
 60:         using var caller = new CancellationTokenSource();
 61:         caller.Cancel();
 62:         var providerCancellation = new OperationCanceledException(caller.Token);
 63: 
 64:         var observed = await Assert.ThrowsAnyAsync<OperationCanceledException>(
 65:                 () => InvokeProviderCancelableAsync(
 66:                     () => Task.FromException<int>(providerCancellation),
 67:                     caller.Token))
 68:             .ConfigureAwait(true);
 69: 
 70:         Assert.Equal(caller.Token, observed.CancellationToken);
 71:     }
 72: 
 73:     private static PostgresException CreateQueryCancelled(string message) =>
 74:         new(
 75:             message,
 76:             "ERROR",
 77:             "ERROR",
 78:             PostgresErrorCodes.QueryCanceled);
 79: 
 80: 
 81:     private static Task<T> InvokeProviderCancelableAsync<T>(
 82:         Func<Task<T>> operation,
 83:         CancellationToken cancellationToken)
 84:     {
 85:         var method = typeof(FederationTopologyService)
 86:             .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
 87:             .Single(candidate =>
 88:                 candidate.Name == "ExecuteProviderCancelableAsync" &&
 89:                 candidate.IsGenericMethodDefinition)
 90:             .MakeGenericMethod(typeof(T));
 91:         return Assert.IsAssignableFrom<Task<T>>(
 92:             method.Invoke(null, [operation, cancellationToken]));
 93:     }
 94: }
