100: public sealed class BugTriage139SixteenthPostgreSqlBoundaryTests
101:     : IClassFixture<EphemeralPostgresFixture>
102: {
103:     private readonly EphemeralPostgresFixture _fixture;
104: 
105:     /// <summary>Initializes the fresh PostgreSQL boundary tests.</summary>
106:     /// <param name="fixture">Fresh PostgreSQL server fixture.</param>
107:     public BugTriage139SixteenthPostgreSqlBoundaryTests(
108:         EphemeralPostgresFixture fixture) =>
109:         _fixture = fixture;
