111:     /// <summary>
112:     /// A real server statement timeout that has already occurred remains the original
113:     /// <see cref="PostgresException"/> when caller cancellation races with propagation.
114:     /// </summary>
115:     [Fact]
116:     public async Task FreshPostgreSql_StatementTimeoutConcurrentWithCallerCancellation_IsPreserved()
117:     {
118:         var testToken = TestContext.Current.CancellationToken;
119:         await using var connection = new NpgsqlConnection(_fixture.ServerConnectionString);
120:         await connection.OpenAsync(testToken).ConfigureAwait(true);
121:         await using (var setup = connection.CreateCommand())
122:         {
123:             setup.CommandText = "SET statement_timeout = 75";
124:             await setup.ExecuteNonQueryAsync(testToken).ConfigureAwait(true);
125:         }
126: 
127:         await using var command = connection.CreateCommand();
128:         command.CommandText = "SELECT pg_sleep(5)";
129:         using var caller = new CancellationTokenSource();
130:         var providerFailure = new TaskCompletionSource<PostgresException>(
131:             TaskCreationOptions.RunContinuationsAsynchronously);
132:         var releaseFailure = new TaskCompletionSource(
133:             TaskCreationOptions.RunContinuationsAsynchronously);
134:         var operation = InvokeProviderCancelableAsync(
135:             async () =>
136:             {
137:                 try
138:                 {
139:                     await command.ExecuteScalarAsync(CancellationToken.None)
140:                         .ConfigureAwait(false);
141:                     return 0;
142:                 }
143:                 catch (PostgresException exception)
144:                     when (exception.SqlState == PostgresErrorCodes.QueryCanceled)
145:                 {
146:                     providerFailure.TrySetResult(exception);
147:                     await releaseFailure.Task.ConfigureAwait(false);
148:                     throw;
149:                 }
150:             },
151:             caller.Token);
152: 
153:         var original = await providerFailure.Task
154:             .WaitAsync(TimeSpan.FromSeconds(20), testToken)
155:             .ConfigureAwait(true);
156:         caller.Cancel();
157:         releaseFailure.TrySetResult();
158: 
159:         var observed = await Assert.ThrowsAsync<PostgresException>(
160:                 async () => await operation.ConfigureAwait(false))
161:             .ConfigureAwait(true);
162:         Assert.Same(original, observed);
163:         Assert.Contains(
164:             "statement timeout",
165:             observed.MessageText,
166:             StringComparison.OrdinalIgnoreCase);
167:     }
