203:     /// <summary>
204:     /// A real administrative <c>pg_cancel_backend</c> produces SQLSTATE 57014 and remains the
205:     /// original <see cref="PostgresException"/> when caller cancellation races with propagation.
206:     /// </summary>
207:     [Fact]
208:     public async Task FreshPostgreSql_AdministrativeCancellationConcurrentWithCallerCancellation_IsPreserved()
209:     {
210:         var testToken = TestContext.Current.CancellationToken;
211:         await using var connection = new NpgsqlConnection(_fixture.ServerConnectionString);
212:         await using var administrator = new NpgsqlConnection(_fixture.ServerConnectionString);
213:         await connection.OpenAsync(testToken).ConfigureAwait(true);
214:         await administrator.OpenAsync(testToken).ConfigureAwait(true);
215: 
216:         int backendProcessId;
217:         await using (var processIdCommand = connection.CreateCommand())
218:         {
219:             processIdCommand.CommandText = "SELECT pg_backend_pid();";
220:             backendProcessId = Convert.ToInt32(
221:                 await processIdCommand.ExecuteScalarAsync(testToken).ConfigureAwait(true),
222:                 System.Globalization.CultureInfo.InvariantCulture);
223:         }
224: 
225:         var lockKey = Random.Shared.Next(1, int.MaxValue);
226:         await using var command = connection.CreateCommand();
227:         command.CommandText = "SELECT pg_advisory_lock(@key), pg_sleep(30);";
228:         command.Parameters.AddWithValue("key", lockKey);
229:         using var caller = new CancellationTokenSource();
230:         var providerFailure = new TaskCompletionSource<PostgresException>(
231:             TaskCreationOptions.RunContinuationsAsynchronously);
232:         var releaseFailure = new TaskCompletionSource(
233:             TaskCreationOptions.RunContinuationsAsynchronously);
234:         var operation = InvokeProviderCancelableAsync(
235:             async () =>
236:             {
237:                 try
238:                 {
239:                     await command.ExecuteScalarAsync(CancellationToken.None).ConfigureAwait(false);
240:                     return 0;
241:                 }
242:                 catch (PostgresException exception)
243:                     when (exception.SqlState == PostgresErrorCodes.QueryCanceled)
244:                 {
245:                     providerFailure.TrySetResult(exception);
246:                     await releaseFailure.Task.ConfigureAwait(false);
247:                     throw;
248:                 }
249:             },
250:             caller.Token);
251: 
252:         await WaitForAdvisoryLockAsync(
253:                 administrator,
254:                 backendProcessId,
255:                 lockKey,
256:                 testToken)
257:             .ConfigureAwait(true);
258:         await using (var cancelCommand = administrator.CreateCommand())
259:         {
260:             cancelCommand.CommandText = "SELECT pg_cancel_backend(@pid);";
261:             cancelCommand.Parameters.AddWithValue("pid", backendProcessId);
262:             var cancelled = await cancelCommand.ExecuteScalarAsync(testToken).ConfigureAwait(true);
263:             Assert.True(Assert.IsType<bool>(cancelled));
264:         }
265: 
266:         var original = await providerFailure.Task
267:             .WaitAsync(TimeSpan.FromSeconds(20), testToken)
268:             .ConfigureAwait(true);
269:         caller.Cancel();
270:         releaseFailure.TrySetResult();
271: 
272:         var observed = await Assert.ThrowsAsync<PostgresException>(
273:                 async () => await operation.ConfigureAwait(false))
274:             .ConfigureAwait(true);
275:         Assert.Same(original, observed);
276:         Assert.Equal(PostgresErrorCodes.QueryCanceled, observed.SqlState);
277:         Assert.Contains(
278:             "user request",
279:             observed.MessageText,
280:             StringComparison.OrdinalIgnoreCase);
281:         Assert.DoesNotContain(
282:             "statement timeout",
283:             observed.MessageText,
284:             StringComparison.OrdinalIgnoreCase);
285:     }
