287:     private static async Task WaitForAdvisoryLockAsync(
288:         NpgsqlConnection administrator,
289:         int backendProcessId,
290:         int lockKey,
291:         CancellationToken cancellationToken)
292:     {
293:         var deadline = DateTimeOffset.UtcNow.AddSeconds(20);
294:         while (DateTimeOffset.UtcNow < deadline)
295:         {
296:             await using var probe = administrator.CreateCommand();
297:             probe.CommandText =
298:                 """
299:                 SELECT EXISTS (
300:                     SELECT 1
301:                     FROM pg_locks
302:                     WHERE pid = @pid
303:                       AND locktype = 'advisory'
304:                       AND granted
305:                       AND classid = 0
306:                       AND objid = @key);
307:                 """;
308:             probe.Parameters.AddWithValue("pid", backendProcessId);
309:             probe.Parameters.AddWithValue("key", lockKey);
310:             var acquired = await probe.ExecuteScalarAsync(cancellationToken).ConfigureAwait(true);
311:             if (Assert.IsType<bool>(acquired))
312:                 return;
313: 
314:             await Task.Delay(TimeSpan.FromMilliseconds(25), cancellationToken).ConfigureAwait(true);
315:         }
316: 
317:         throw new TimeoutException("PostgreSQL backend did not acquire the administrative-cancel gate lock.");
318:     }
